#include <algorithm>
#include <array>
#include <functional>
#include <iostream>
#include <map>
#include <numeric>
#include <stdexcept>
#include <vector>
using namespace std;using ll=long long;using R=vector<int>;using P=vector<ll>;
void need(bool b,const char*s){if(!b)throw runtime_error(s);}int bit(unsigned b){return __builtin_ctz(b);}void trim(P&p){while(p.size()>1&&!p.back())p.pop_back();}P add(P p,P const&q,ll c=1){p.resize(max(p.size(),q.size()));for(size_t i=0;i<q.size();i++)p[i]+=c*q[i];trim(p);return p;}P mul(P const&p,P const&q){P r(p.size()+q.size()-1);for(size_t i=0;i<p.size();i++)for(size_t j=0;j<q.size();j++)r[i+j]+=p[i]*q[j];trim(r);return r;}P xp(P p,int n){p.insert(p.begin(),n,0);trim(p);return p;}P shifted(P const&p,int s){P r{0},power{1};for(ll a:p){r=add(r,power,a);power=mul(power,P{s,1});}return r;}P D(P const&p){return add(xp(p,2),xp(add(shifted(p,1),shifted(p,-1),-1),1));}P basis(int k,int parity){P p=parity?P{0,1}:P{0,0,1};for(int j=1;j<=k;j++)p=mul(p,P{-j*j,0,1});return p;}vector<ll>coords(P p,int parity){vector<ll>c;int low=parity?1:2;while((int)p.size()-1>=low){int k=((int)p.size()-1-low)/2;P b=basis(k,parity);need(b.size()==p.size(),"profile parity");ll v=p.back();if(c.size()<=size_t(k))c.resize(k+1);c[k]+=v;p=add(p,b,-v);}need(all_of(p.begin(),p.end(),[](ll v){return v==0;}),"no constant boundary");return c;}
R tournament(int n,int code){R r(n);int p=0;for(int i=0;i<n;i++)for(int j=i+1;j<n;j++){int a=i,b=j;if(!(code>>p++&1))swap(a,b);r[a]|=1<<b;}return r;}R sub(R const&q,int root,R const&t){R r;vector<int>o;for(int i=0;i<(int)q.size();i++)if(i!=root)o.push_back(i);int N=o.size(),m=t.size();r.resize(N+m);for(int i=0;i<N;i++){for(int j=0;j<N;j++)if(q[o[i]]>>o[j]&1)r[i]|=1<<j;for(int j=0;j<m;j++)if(q[o[i]]>>root&1)r[i]|=1<<(N+j);else r[N+j]|=1<<i;}for(int i=0;i<m;i++)r[N+i]|=t[i]<<N;return r;}R trans(int n){R r(n);for(int i=0;i<n;i++)for(int j=i+1;j<n;j++)r[i]|=1<<j;return r;}R join(R const&a,R const&b){int n=a.size(),m=b.size();R r=a;for(int&i:r)i|=((1<<m)-1)<<n;for(int x:b)r.push_back(x<<n);return r;}bool active(R const&q,int r){for(int o=0;o<(int)q.size();o++)for(int i=0;i<(int)q.size();i++)if((q[r]>>o&1)&&(q[o]>>i&1)&&(q[i]>>r&1))return true;return false;}
ll H(R const&r){int n=r.size();if(!n)return 1;int N=1<<n;vector<ll>d(size_t(N)*n);for(int v=0;v<n;v++)d[size_t(1<<v)*n+v]=1;for(int s=1;s<N;s++)for(int v=0;v<n;v++)if(s>>v&1){unsigned out=r[v]&~s;while(out){int w=bit(out);out&=out-1;d[size_t(s|1<<w)*n+w]+=d[size_t(s)*n+v];}}ll h=0;for(int v=0;v<n;v++)h+=d[size_t(N-1)*n+v];return h;}
map<R,P>cache;P B(R const&r){auto it=cache.find(r);if(it!=cache.end())return it->second;int n=r.size(),N=1<<n;vector<int>cyc(N);for(int s=0;s<n;s++){function<void(int,int,int)>go=[&](int v,int mask,int len){if(len>=3&&(len&1)&&(r[v]>>s&1))cyc[mask]++;unsigned out=r[v]&~mask&~((1<<(s+1))-1);while(out){int w=bit(out);out&=out-1;go(w,mask|1<<w,len+1);}};go(s,1<<s,1);}vector<P>d(N);d[0]=P{1};for(int s=1;s<N;s++){int b=s&-s;d[s]=xp(d[s^b],1);for(int t=s;t;t=(t-1)&s)if((t&b)&&cyc[t])d[s]=add(d[s],xp(d[s^t],1),2*cyc[t]);}ll h=accumulate(d.back().begin(),d.back().end(),0LL);need(h==H(r),"odd-cycle vs endpoint H");cache[r]=d.back();return d.back();}
ll ipow(ll a,int k){ll b=1;while(k--)b*=a;return b;}
int main(){int contexts=0,virtuals=0,passive=0,physical=0;for(int n=1;n<=4;n++)for(int code=0;code<(1<<(n*(n-1)/2));code++){R q=tournament(n,code);for(int r=0;r<n;r++){contexts++;int N=n-1;bool act=active(q,r);vector<P>images;for(int m=0;m<=6;m++)images.push_back(B(sub(q,r,trans(m))));for(int par=0;par<2;par++)for(int k=0;k<3;k++){P f=basis(k,par),got{0};for(int j=0;j<(int)f.size();j++)got=add(got,images[j],f[j]);P lower=act?xp(D(f),N-2):xp(f,N);auto c=coords(add(got,lower,-1),(N+par)%2);need(all_of(c.begin(),c.end(),[](ll x){return x>=0;}),"virtual triangular suboperator");virtuals++;if(!act){P exterior=images[0];need(got==mul(exterior,f),"passive bin multiplication");passive++;}}}}
R tri{2,4,1},pad{2,0},odd=join(tri,R{0});using C=pair<R,int>;vector<vector<C>>words{{{tri,0}},{{odd,0}},{{pad,0},{tri,1}},{{odd,3}},{{odd,3},{tri,2}},{{R{0},0}}, {}};vector<vector<ll>>hist;for(R seed:{R{0},trans(2),tri})for(auto const&word:words){R t=seed;ll h=H(t),factor=1;bool act=false;for(auto const&c:word){act|=active(c.first,c.second);factor*=H(c.first);}vector<ll>counts{h};for(int m=1;m<=3;m++){for(auto const&c:word)t=sub(c.first,c.second,t);ll got=H(t);counts.push_back(got);physical++;if(!act)need(got==h*ipow(factor,m),"passive geometric");else for(int k=0;k<=m/2;k++)need(got>=h*ipow(k+1,2*m-4*k),"physical path lower bound");}hist.push_back(counts);}
cout<<"{\"status\":\"PASS\",\"contexts\":"<<contexts<<",\"virtual_columns\":"<<virtuals<<",\"passive_columns\":"<<passive<<",\"independent_bin_graphs\":"<<cache.size()<<",\"physical_counts\":"<<physical<<",\"counts\":[";for(int i=0;i<(int)hist.size();i++){if(i)cout<<',';cout<<'[';for(int j=0;j<(int)hist[i].size();j++){if(j)cout<<',';cout<<hist[i][j];}cout<<']';}cout<<"]}\n";}
